class MixControl:public juce::Component {
 juce::Label label;std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> attachment;
public:
 AutomationSlider slider;
 MixControl(SynthProcessor& p,juce::String id,juce::String title,bool fader=false,bool sourceLevel=false){using namespace juce;addAndMakeVisible(label);addAndMakeVisible(slider);label.setText(title,dontSendNotification);label.setFont(FontOptions(nd::number("fontSize",8.5f),Font::bold));label.setJustificationType(Justification::centred);label.setColour(Label::textColourId,UiStyle::moduleInk());label.setInterceptsMouseClicks(false,false);auto* parameter=p.state.getParameter(id);slider.bindAutomation(parameter,&p);setComponentID("mix-control:"+id);getProperties().set("parameterIndex",parameter->getParameterIndex());slider.setSliderStyle(fader?Slider::LinearVertical:Slider::RotaryHorizontalVerticalDrag);slider.setRotaryParameters(MathConstants<float>::pi*1.24f,MathConstants<float>::pi*2.76f,true);slider.setTextBoxStyle(fader?Slider::TextBoxBelow:Slider::NoTextBox,false,52,18);slider.setTooltip(parameter->getName(80)+" / right-click: automation / drop a macro to link");attachment=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,id,slider);if(fader){slider.textFromValueFunction=[sourceLevel](double v){float db=sourceLevel?Decibels::gainToDecibels((float)v,-60.f):(float)v;return db<=-60?String("-inf"):String(db,1)+" dB";};slider.valueFromTextFunction=[sourceLevel](const String& text){float db=text.containsIgnoreCase("inf")?-60.f:text.getFloatValue();return sourceLevel?mixDbGain(db):db;};}slider.setColour(Slider::textBoxTextColourId,UiStyle::moduleInk());slider.setDoubleClickReturnValue(true,parameter->convertFrom0to1(parameter->getDefaultValue()));slider.updateText();}
 ~MixControl()override{attachment.reset();}
 void resized()override{label.setBounds(0,0,getWidth(),13);slider.setBounds(0,13,getWidth(),getHeight()-13);}
};
