 std::array<MixControl*,5> balances{};std::array<int,5> lastRoutes{{-99,-99,-99,-99,-99}};int width=108,spacing=110;
 void timerCallback()override{auto assets=std::atomic_load(&p.importedAssets);for(int channel=0;channel<5;++channel){int source=channel==0?4:channel==4?3:channel-1;int mode=source<3?(int)p.value("osc"+juce::String(source+1)+"routing"):(int)p.value(source==3?"noiseRouting":"subRouting")-1;float f0=0,f1=0;if(mode<0){if(assets&&assets->expansion&&!assets->userSource){f0=assets->expansion->filterRouting[0][source];f1=assets->expansion->filterRouting[1][source];}else f0=1;}else if(mode==0)f0=1;else if(mode==1)f1=1;else if(mode==2){f1=p.value("mix"+mixSources[source]+"Balance");f0=1-f1;}routes[channel]->getProperties().set("filterRouteMask",mode==2?3:((f0>0?1:0)|(f1>0?2:0)));balances[channel]->setEnabled(mode==2);if(mode!=2||lastRoutes[channel]!=2)balances[channel]->slider.setValue(mode==2?p.value("mix"+mixSources[source]+"Balance"):f0+f1>0?f1/(f0+f1):.5f,juce::dontSendNotification);lastRoutes[channel]=mode;if(source>=3)routes[channel]->changeItemText(1,f0>0&&f1>0?"Auto: F1+2":f0>0?"Auto: F1":f1>0?"Auto: F2":"Auto: Main");}for(int f=0;f<2;++f){int mode=(int)p.value("filter"+juce::String(f+1)+"route");bool toFilter=mode==3||(mode==0&&f==0&&p.value("filterSerial")>.5f);routes[5+f]->getProperties().set("filterRouteMask",toFilter?(f==0?2:1):0);routes[5+f]->changeItemText(1,f==0&&p.value("filterSerial")>.5f?"Auto: F2":"Auto: Main");}for(auto* combo:routes)combo->setSelectedId(combo->getSelectedId(),juce::dontSendNotification);cables.repaint();repaint();}
 void refreshRoutingMasks(){auto assets=std::atomic_load(&p.importedAssets);for(int channel=0;channel<5;++channel){int source=channel==0?4:channel==4?3:channel-1;int mode=source<3?(int)p.value("osc"+juce::String(source+1)+"routing"):(int)p.value(source==3?"noiseRouting":"subRouting")-1;int mask=mode==0?1:mode==1?2:mode==2?3:0;if(mode<0){mask=1;if(assets&&assets->expansion&&!assets->userSource)mask=(assets->expansion->filterRouting[0][source]>0?1:0)|(assets->expansion->filterRouting[1][source]>0?2:0);}routes[channel]->getProperties().set("filterRouteMask",mask);routes[channel]->getProperties().set("routingIndex",source<3?mode:mode+1);}for(int f=0;f<2;++f){int mode=(int)p.value("filter"+juce::String(f+1)+"route");bool toFilter=mode==3||(mode==0&&f==0&&p.value("filterSerial")>.5f);routes[5+f]->getProperties().set("filterRouteMask",toFilter?(f==0?2:1):0);routes[5+f]->getProperties().set("routingIndex",mode);}for(int b=0;b<2;++b)routes[7+b]->getProperties().set("routingIndex",(int)p.value("mixBus"+juce::String(b+1)+"Route"));}
