 explicit MixPage(SynthProcessor& processor):p(processor),cables(processor){using namespace juce;setComponentID("mix-page");setLookAndFeel(&theme);theme.attach(*this);setOpaque(true);const String names[]={"SUB","OSC A","OSC B","OSC C","NOISE","FILTER 1","FILTER 2","BUS 1","BUS 2","MAIN","DIRECT"};
 for(int channel=0;channel<11;++channel){int x=channel*spacing;String enabled=channel==0?"subEnabled":channel<4?"osc"+String(channel)+"enabled":channel==4?"noiseEnabled":channel<7?"filter"+String(channel-4)+"enabled":"mix"+String(channel==7?"Bus1":channel==8?"Bus2":channel==9?"Main":"Direct")+"Enabled";auto* header=headers.add(new TextButton(names[channel]));addAndMakeVisible(header);header->setBounds(x,0,width,28);header->setClickingTogglesState(true);header->getProperties().set("oscHeader",true);header->getProperties().set("roundedModTab",true);header->getProperties().set("lightModuleHeader",true);header->getProperties().set("oscLabelHeader",true);header->getProperties().set("oscPowerHeader",true);header->setColour(TextButton::textColourOnId,UiStyle::moduleInk());header->setColour(TextButton::textColourOffId,UiStyle::moduleInk());header->getProperties().set("parameterIndex",p.state.getParameter(enabled)->getParameterIndex());powerLinks.push_back(std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,enabled,*header));
 String pan,level;
 if(channel<5){int source=channel==0?4:channel==4?3:channel-1;auto key=mixSources[source];route(source<3?"osc"+String(source+1)+"routing":source==3?"noiseRouting":"subRouting",x,channel);balances[channel]=control("mix"+key+"Balance","FILTER 1 / 2",x+26,61,57,54);control("mix"+key+"Bus1","BUS 1",x+4,124,48,53);control("mix"+key+"Bus2","BUS 2",x+56,124,48,53);pan=source<3?"osc"+String(source+1)+"pan":source==3?"noisePan":"subPan";level=source<3?"osc"+String(source+1)+"level":source==3?"noise":"sub";}
 else if(channel<7){auto key="Filter"+String(channel-4),id="filter"+String(channel-4);route(id+"route",x,channel);control("mix"+key+"Bus1","BUS 1",x+4,124,48,53);control("mix"+key+"Bus2","BUS 2",x+56,124,48,53);pan=id+"pan";level="mix"+key+"Db";}
 else {String key=channel==7?"Bus1":channel==8?"Bus2":channel==9?"Main":"Direct";if(channel<9)route("mix"+key+"Route",x,channel);pan="mix"+key+"Pan";level="mix"+key+"Db";}
 control(pan,"PAN",x+3,183,47,56);control(level,"LEVEL",x+48,184,57,176,true,channel<5);
 }
 addAndMakeVisible(cables);cables.setBounds(0,362,1208,36);timerCallback();startTimerHz(25);}
